CREATE DATABASE IF NOT EXISTS machun1 CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
USE machun1;
CREATE TABLE IF NOT EXISTS users (username VARCHAR(64) PRIMARY KEY, pwd CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, username VARCHAR(64) NOT NULL, expires_at DATETIME(3) NOT NULL, INDEX session_expiry (expires_at), FOREIGN KEY (username) REFERENCES users(username)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS catalog_meta (id INT PRIMARY KEY, version VARCHAR(128) NOT NULL, date CHAR(10) NOT NULL, provenance JSON NOT NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS songs (id VARCHAR(64) PRIMARY KEY, title VARCHAR(512) NOT NULL, genre VARCHAR(64) NOT NULL, version VARCHAR(64) NOT NULL, cover_url VARCHAR(1024) NOT NULL, aliases JSON NOT NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS charts (song_id VARCHAR(64) NOT NULL, difficulty ENUM('EXP','MAS','ULT') NOT NULL, constant DECIMAL(3,1) NOT NULL, bpm DOUBLE NULL, notes JSON NULL, scoring BOOLEAN NOT NULL, position INT NOT NULL, PRIMARY KEY(song_id,difficulty), FOREIGN KEY(song_id) REFERENCES songs(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS workspaces (username VARCHAR(64) PRIMARY KEY, revision INT UNSIGNED NOT NULL DEFAULT 0, legacy_migrated BOOLEAN NOT NULL DEFAULT FALSE, sources_migrated BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(username) REFERENCES users(username)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS scores (username VARCHAR(64) NOT NULL, song_id VARCHAR(64) NOT NULL, difficulty ENUM('EXP','MAS','ULT') NOT NULL, score INT UNSIGNED NOT NULL, source ENUM('manual','rin','otogame','lxns','munet') NOT NULL, combo ENUM('fc','aj','ajc') NULL, full_chain ENUM('fchain','gold','platinum') NULL, updated_at VARCHAR(64) NOT NULL, PRIMARY KEY(username,song_id,difficulty), FOREIGN KEY(username) REFERENCES users(username), CHECK(score <= 1010000)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS personal_aliases (username VARCHAR(64) NOT NULL, song_id VARCHAR(64) NOT NULL, aliases JSON NOT NULL, PRIMARY KEY(username,song_id), FOREIGN KEY(username) REFERENCES users(username)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS source_states (username VARCHAR(64) NOT NULL, source ENUM('rin','munet','otogame','lxns') NOT NULL, state JSON NOT NULL, PRIMARY KEY(username,source), FOREIGN KEY(username) REFERENCES users(username)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS _machun_migrations (name VARCHAR(128) PRIMARY KEY, applied_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
INSERT IGNORE INTO _machun_migrations (name) VALUES ('0001_accounts');
